def looks_like_claude_code(raw):
    """True when the payload carries a field only Claude Code has been seen to send."""
    return isinstance(raw, dict) and any(marker in raw for marker in OBSERVED_MARKERS)

PROBES = {"looks_like_claude_code": looks_like_claude_code}

UNREADABLE_NAME = ""

def wire_name_of(raw, key):
    """The event name under `key`: text, None when absent, UNREADABLE_NAME when not text.

    Total over anything `json.loads` can return: a payload that is not an object names no
    event, and a name that is not a string is not one any adapter can map.
    """
    name = raw.get(key) if isinstance(raw, dict) else None
    if name is None or isinstance(name, str):
        return name
    return UNREADABLE_NAME

def _wire_name(cfg, raw):
    for key in cfg["claims"].get("event_key", ()):
        name = wire_name_of(raw, key)
        if name is not None:
            return name
    return None

def _rejected_by_markers(c, raw):
    for marker in c.get("reject_markers", ()):
        if marker in raw:
            return True
    for probe, markers in c.get("reject_markers_unless_probe", {}).items():
        if any(marker in raw for marker in markers) and not PROBES[probe](raw):
            return True
    return any(PROBES[probe](raw) for probe in c.get("reject_probes", ()))

def _accepted_by_markers(c, raw, name):
    accept = c.get("accept_markers", ())
    if not accept or any(marker in raw for marker in accept):
        return True
    return any(
        name == event_name and all(key in raw for key in required)
        for event_name, required in c.get("accept_when_all", {}).items()
    )

def _disqualified(cfg, c, raw, name):
    """Every reason an entry declines a payload once its wire event name is known."""
    if name not in cfg["events"] and not (c.get("accept_any_name") and isinstance(name, str)):
        return True
    if "client_types" in c and raw.get("client_type") not in c["client_types"]:
        return True
    return _rejected_by_markers(c, raw)

def hj_claims(cfg, raw):
    """True when this payload matches the entry's marker discipline."""
    if not isinstance(raw, dict):
        return False
    c = cfg["claims"]
    name = _wire_name(cfg, raw)
    # A positive self-identification beats a shared event name, accept_names included.
    if raw.get("client_type") in c.get("reject_client_types", ()):
        return False
    if name in c.get("accept_names", ()):
        return True
    return not _disqualified(cfg, c, raw, name) and _accepted_by_markers(c, raw, name)

def _segment(node, part):
    """One path segment: a dict key, or `key[N]` indexing the list under it."""
    if part.endswith("]") and "[" in part:
        key, _, index = part[:-1].partition("[")
        items = node.get(key) if isinstance(node, dict) else None
        i = int(index)
        return items[i] if isinstance(items, (list, tuple)) and len(items) > i else None
    return node.get(part) if isinstance(node, dict) else None

def _walk(node, path):
    """A dotted path off `node`; `a[].b` joins `b` over `a`'s dict items, `a[0]` indexes."""
    if "[]." in path:
        head, sub = path.split("[].", 1)
        items = _walk(node, head)
        if not isinstance(items, (list, tuple)):
            return None
        joined = "\n".join(str(item.get(sub, "")) for item in items if isinstance(item, dict))
        return joined or None
    for part in path.split("."):
        node = _segment(node, part)
        if node is None:
            return None
    return node

def _lookup(raw, ti, key):
    """One config key: a `tool_input.` path walks the decoded tool input, else the payload."""
    if key.startswith("tool_input."):
        return _walk(ti, key[len("tool_input.") :])
    return _walk(raw, key)

def _field(raw, ti, chain):
    value = None
    for key in chain:
        if value:
            break
        value = value or _lookup(raw, ti, key)
    return value

_FIELD_META = ("tool_input", "content_only_for_write_tools", "stringify")

def _tool_input_raw(cfg, raw):
    if not isinstance(raw, dict):
        return None
    for key in cfg["fields"].get("tool_input", ("tool_input",)):
        value = raw.get(key)
        if value is not None:
            return value
    return None

def _canonical_of(cfg, name):
    """The canonical event for one wire name; an entry with no `events` at all (antigravity,
    whose payloads never carry one) maps the shape-inferred name back through `wire_events`."""
    events = cfg["events"]
    if not events:
        return {wire: canonical for canonical, wire in cfg.get("wire_events", {}).items()}.get(name, UNKNOWN)
    return events.get(name, UNKNOWN)

def hj_parse(cfg, raw, wire=None):
    """Normalise one payload along the entry's ordered field-fallback chains.

    `wire` is the pre-resolved wire event name for the shape-inferred families; the
    marker families resolve it from the payload's own event key.
    """
    ti = tool_input_of(_tool_input_raw(cfg, raw))
    fields = {name: _field(raw, ti, chain) for name, chain in cfg["fields"].items() if name not in _FIELD_META}
    if cfg["fields"].get("content_only_for_write_tools") and fields.get("tool") not in cfg["tools"].get("write", ()):
        fields["content"] = None
    if isinstance(fields.get("output"), (dict, list)):
        fields["output"] = _json.dumps(fields["output"])
    for name in cfg["fields"].get("stringify", ()):
        if fields.get(name) is not None:
            fields[name] = str(fields[name])
    return Event(
        cfg["agent"],
        _canonical_of(cfg, wire if wire is not None else _wire_name(cfg, raw)),
        tool=fields.get("tool"),
        command=fields.get("command"),
        path=fields.get("path"),
        content=fields.get("content"),
        output=fields.get("output"),
        prompt=fields.get("prompt"),
        session_id=fields.get("session_id"),
        tool_use_id=fields.get("tool_use_id"),
        cwd=fields.get("cwd"),
        raw=raw,
    )

_ESCALATE_FROM_TRANSFORM = "escalate_from_transform"

_TRANSFORM_MISSING_INPUT = "transform_missing_input"

def hj_reverse(cfg):
    """Canonical event -> wire name: the naive inverse, then the entry's pinned overrides.

    One wire name per canonical event, which is a real limit and not an oversight (R3, gap 4).
    Cursor is where it bites: `pre_tool` pins to `preToolUse`, and Cursor honours `ask` only at
    `beforeShellExecution` / `beforeMCPExecution`. So installing at `pre_tool` forecloses `ask`
    before dispatch is ever reached -- the runtime degrade to `deny` is honest about it, but the
    install already chose. Deny-style policies, which is all that ships today, are unaffected.

    The day an ask-style Cursor policy exists, this map has to select by decision dialect
    (deny -> `preToolUse`, ask -> `beforeShellExecution`) and become one-to-many. Recorded here
    rather than built, so the resolution is not re-litigated from scratch; the three facts it
    rests on are pinned in tests/test_cursor_ask_dialect.py.
    """
    reverse = {}
    for name, canonical in cfg["events"].items():
        if canonical != UNKNOWN:
            reverse[canonical] = name
    reverse.update(cfg.get("wire_events", {}))
    return reverse

def _context_value(v, decision):
    if v.get("context_source") == "context":
        return decision.context
    if v.get("context_source") == "reason":
        return decision.reason
    return None

def _context_body(name, value):
    return _json.dumps({"hookSpecificOutput": {"hookEventName": name, "additionalContext": value}}), 0

def _note_for(v, decision, at_gate, missing_input):
    notes = v.get("degrade_notes", {})
    if decision.outcome == ESCALATE:
        if degraded_from(decision) == TRANSFORM and _ESCALATE_FROM_TRANSFORM in notes:
            return notes[_ESCALATE_FROM_TRANSFORM]
        if at_gate and "escalate_gate" in notes:
            return notes["escalate_gate"]
        return notes.get("escalate")
    if decision.outcome == TRANSFORM:
        if missing_input and _TRANSFORM_MISSING_INPUT in notes:
            return notes[_TRANSFORM_MISSING_INPUT]
        return notes.get("transform")
    return None

def _default_for(v, decision, at_gate, wire=None):
    gate_defaults = v.get("gate_reason_defaults", {})
    if wire in gate_defaults:
        return gate_defaults[wire]
    defaults = v.get("reason_defaults", {})
    key = {DENY: "deny", ESCALATE: "escalate", TRANSFORM: "transform"}.get(decision.outcome, "deny")
    if at_gate and key + "_gate" in defaults:
        return defaults[key + "_gate"]
    return defaults.get(key, "blocked by policy")

def _refusal_text(v, decision, at_gate, wire=None):
    note = _note_for(v, decision, at_gate, decision.updated_input is None)
    default = _default_for(v, decision, at_gate, wire)
    if note and "%s" in note:
        # A template note fills (the reason or its default, the wire event name) itself.
        return note % (decision.reason or default, wire)
    reason = decision.reason
    if v.get("note_style") == "suffix":
        reason = reason or default
        return "%s (%s)" % (reason, note) if note else reason
    text = "%s (%s)" % (reason, note) if reason and note else (note or reason)
    return text or default

def _g1_allow(v, decision, wire, name, words):
    value = _context_value(v, decision)
    if wire in v.get("context_events", ()) and value:
        return _context_body(name, value)
    if wire in v.get("allow_silent_events", ()):
        return "", 0
    if "allow" in words:
        out = {"decision": words["allow"]}
        if v.get("allow_context_key") and decision.outcome == ALLOW and value:
            out[v["allow_context_key"]] = value
        return _json.dumps(out), 0
    return "", 0

def _g1_transform(v, decision, name, words):
    """None when the transform isn't representable here; `_g1` falls through to the block path."""
    if v.get("transform_grammar") == "hook_specific_tool_input":
        return _json.dumps({"hookSpecificOutput": {"tool_input": decision.updated_input}}), 0
    if decision.updated_input is None:
        return None
    if v.get("transform_grammar") == "top_level_updated_input":
        out = {"decision": words.get("transform", "allow"), "updatedInput": decision.updated_input}
        if decision.reason:
            out["reason"] = decision.reason
        return _json.dumps(out), 0
    return _json.dumps({"hookSpecificOutput": {"hookEventName": name, "updatedInput": decision.updated_input}}), 0

def _g1(v, gate, decision, wire, name):
    """Block dialect: a top-level decision word, or silence/context where nothing is read."""
    words = dict(v.get("words", {}))
    words.update(v.get("words_at", {}).get(wire, {}))
    at_context_event = wire in v.get("context_events", ())
    if decision.outcome in (ALLOW, VOUCH, WARN):
        return _g1_allow(v, decision, wire, name, words)
    if decision.outcome == TRANSFORM and gate["honours_transform"]:
        transformed = _g1_transform(v, decision, name, words)
        if transformed is not None:
            return transformed
    if (
        decision.outcome == ESCALATE
        and gate["honours_escalate"]
        and "escalate" in words
        # An escalate the dispatcher degraded a transform into is a block where the entry
        # names that degradation (antigravity): prompting would offer the unmodified call.
        and not (degraded_from(decision) == TRANSFORM and _ESCALATE_FROM_TRANSFORM in v.get("degrade_notes", {}))
    ):
        reason = decision.reason or _default_for(v, decision, at_gate=True, wire=wire)
        return _json.dumps({"decision": words["escalate"], "reason": reason}), 0
    out = {"decision": words.get("block", "block"), "reason": _refusal_text(v, decision, at_gate=False, wire=wire)}
    if at_context_event and v.get("context_source") == "context" and decision.context:
        out["hookSpecificOutput"] = {"hookEventName": name, "additionalContext": decision.context}
    return _json.dumps(out), 0

_PERMISSION_DECISION_REASON = "permissionDecisionReason"

def _g2(v, gate, decision, name):
    """Permission gate: `hookSpecificOutput.permissionDecision`, filled from the word table."""
    if decision.outcome in (ALLOW, WARN):
        return "", 0
    words = v.get("words", {})
    out = {"hookEventName": name}
    if decision.outcome == VOUCH:
        if "vouch" not in words:
            return "", 0
        out["permissionDecision"] = words["vouch"]
        if decision.reason:
            out[_PERMISSION_DECISION_REASON] = decision.reason
    elif (
        decision.outcome == TRANSFORM
        and gate["honours_transform"]
        and not (decision.updated_input is None and _TRANSFORM_MISSING_INPUT in v.get("degrade_notes", {}))
    ):
        out["permissionDecision"] = words.get("transform", "allow")
        out["updatedInput"] = decision.updated_input
        if decision.reason:
            out[_PERMISSION_DECISION_REASON] = decision.reason
    elif decision.outcome == ESCALATE and gate["honours_escalate"] and "escalate" in words:
        out["permissionDecision"] = words["escalate"]
        out[_PERMISSION_DECISION_REASON] = decision.reason or _default_for(v, decision, at_gate=True)
    else:
        out["permissionDecision"] = words.get("deny", "deny")
        out[_PERMISSION_DECISION_REASON] = _refusal_text(v, decision, at_gate=True)
    return _json.dumps({"hookSpecificOutput": out}), 0

def hj_respond(cfg, decision, event, wire=None):
    """(stdout_text, exit_code) in this entry's dialect for the gate the payload names.

    `wire` is the pre-resolved wire event name for the shape-inferred families; the
    marker families resolve it from the payload's own event key.
    """
    v = cfg["verdicts"]
    if wire is None:
        wire = _wire_name(cfg, event.raw or {})
    if wire in v.get("empty_object_events", ()):
        return _json.dumps({}), 0
    if wire is None:
        wire = v.get("default_wire_event")
        if wire is None and v.get("missing_wire") == "reverse_map":
            wire = hj_reverse(cfg).get(event.event)
    name = wire if v.get("echo") == "payload" else hj_reverse(cfg).get(event.event, "PreToolUse")
    gate = v["gates"].get(wire)
    if gate is None:
        value = _context_value(v, decision)
        if wire in v.get("context_events", ()) and value:
            return _context_body(name, value)
        return "", 0
    if gate["grammar"] == "G2":
        return _g2(v, gate, decision, name)
    return _g1(v, gate, decision, wire, name)

_WINDOWS_KEYS = ("commandWindows", "windows")

_MATCHER_EVENTS = (PRE_TOOL, POST_TOOL, TOOL_FAILURE)

def _hook_dict(cfg, command):
    entry = {"type": "command", "command": command}
    for key, value in cfg["hook_entry"].get("entry_extra", {}).items():
        if key in _WINDOWS_KEYS:
            entry[key] = powershell_command(command)
        else:
            entry[key] = value
    return entry

def _flat_list_wrapper(hook_entry, reverse, canonical_events, command, matcher):
    rules = []
    for ev in canonical_events:
        name = reverse.get(ev)
        if not name:
            continue
        rule = {"event": name, "command": command}
        if matcher and hook_entry["matcher"] and ev in _MATCHER_EVENTS:
            rule["matcher"] = matcher
        rules.append(rule)
    return rules

def _cursor_wrapper(cfg, reverse, canonical_events, command, *, fail_closed):
    gates = cfg["verdicts"]["answer_events"]
    allow_silent = cfg["verdicts"].get("allow_silent_events", ())
    hooks = {}
    for ev in canonical_events:
        name = reverse.get(ev)
        if not name:
            continue
        entry = {"command": command}
        if fail_closed and name in gates and name not in allow_silent:
            entry["failClosed"] = True
        hooks.setdefault(name, []).append(entry)
    return {"version": 1, "hooks": hooks}

def _flat_entries_wrapper(hook_entry, reverse, canonical_events, command):
    hooks = {}
    for ev in canonical_events:
        name = reverse.get(ev)
        if not name:
            continue
        hooks.setdefault(name, []).append({"command": command})
        extra = hook_entry.get("also_wires", {}).get(ev)
        if extra:
            hooks.setdefault(extra, []).append({"command": command})
    return {"hooks": hooks}

def _default_wrapper(cfg, reverse, canonical_events, command, matcher):
    hook_entry = cfg["hook_entry"]
    hooks = {}
    for ev in canonical_events:
        name = reverse.get(ev)
        if not name:
            continue
        entry = {"hooks": [_hook_dict(cfg, command)]}
        if matcher and hook_entry["matcher"] and ev in _MATCHER_EVENTS:
            entry["matcher"] = matcher
        hooks.setdefault(name, []).append(entry)
    if hook_entry.get("group"):
        return {hook_entry["group"]: hooks}
    return hooks if hook_entry.get("bare") else {"hooks": hooks}

def hook_entry_config(cfg, canonical_events, command, matcher=None, *, fail_closed=True):
    """The vendor's hooks-config fragment wiring `command` for these canonical events.

    `fail_closed` is read only by the `cursor` wrapper, whose gates fail open unless the
    entry says otherwise; a False installs an observer, not a gate.
    """
    hook_entry = cfg["hook_entry"]
    reverse = hj_reverse(cfg)
    wrapper = hook_entry["wrapper"]
    if wrapper == "flat_list":
        return _flat_list_wrapper(hook_entry, reverse, canonical_events, command, matcher)
    if wrapper == "cursor":
        return _cursor_wrapper(cfg, reverse, canonical_events, command, fail_closed=fail_closed)
    if wrapper == "flat_entries":
        return _flat_entries_wrapper(hook_entry, reverse, canonical_events, command)
    return _default_wrapper(cfg, reverse, canonical_events, command, matcher)


